public Long createParam(ProductParamBo bo) {
    // ① 产品必须存在，否则后续所有写入都是孤儿数据
    if (productDao.getById(bo.getPackageId()) == null) {
        throw new BizException("产品不存在: " + bo.getPackageId());
    }
    // ② 参数编码：不传就按 03 段内最大号加一，由服务端分配
    String paramCode = StringUtils.isNotBlank(bo.getParamCode())
            ? bo.getParamCode()
            : nextParamCode(bo.getPackageId());   // 03 段最大号 + 1
    // ③ 类型白名单：这一列后面直接参与展示与计算，值域必须收口
    if (!PARAM_TYPE_WHITE.contains(bo.getParamType())) {
        throw new BizException("不支持的参数类型: " + bo.getParamType());
    }
    // ④ 公式语法校验：带公式的参数必须是合法表达式，不能留到计算时才炸
    if (StringUtils.isNotBlank(bo.getFormula())) {
        formulaValidator.check(bo.getFormula());
    }
    // ⑤ 按 (packageId, paramCode) upsert：同一产品下编码唯一
    ProductParam exist = paramDao.queryByPackageAndCode(bo.getPackageId(), paramCode);
    if (exist != null) {
        bo.setId(exist.getId());
        paramDao.updateById(bo);
        return exist.getId();
    }
    ProductParam param = new ProductParam();
    BeanUtils.copyProperties(bo, param);
    param.setParamCode(paramCode);
    param.setCreateTime(new Date());
    paramDao.insert(param);
    return param.getId();
}

@Transactional(rollbackFor = Exception.class)
public void saveMyProduct(MyProductBo bo) {
    // 国产化配置与主推配置都是「整套替换」语义，先按 modelId + version 删旧
    localizationDao.deleteByModelAndVersion(bo.getModelId(), bo.getVersion());
    recommendDao.deleteByModelAndVersion(bo.getModelId(), bo.getVersion());
    if (CollectionUtils.isEmpty(bo.getLocalizationList())
            && CollectionUtils.isEmpty(bo.getRecommendList())) {
        // 空配置不是错误，但要留痕：否则「为什么这个产品没配置」无从查起
        log.warn("myProduct saved with empty config, modelId: {}, version: {}",
                bo.getModelId(), bo.getVersion());
        return;
    }
    if (!CollectionUtils.isEmpty(bo.getLocalizationList())) {
        localizationDao.insertBatch(toLocalizationRows(bo));
    }
    if (!CollectionUtils.isEmpty(bo.getRecommendList())) {
        recommendDao.insertBatch(toRecommendRows(bo));
    }
}
